private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int index = i;
    while (bb.hasRemaining()) {
        int b = bb.get();
        if ((b & 0x80) == 0) {
            sb.append((char) b);
            index++;
        } else if ((b & 0xE0) == 0xC0) {
            int b1 = bb.get();
            sb.append((char) (((b & 0x1F) << 6) | (b1 & 0x3F)));
            index += 2;
        } else if ((b & 0xF0) == 0xE0) {
            int b1 = bb.get();
            int b2 = bb.get();
            sb.append((char) (((b & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F)));
            index += 3;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 encoding");
        }
    }
    return index;
}

