public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Create a new bipartite graph with the given number of vertices
    BipartiteGraph<V,E> graph = new BipartiteGraph<>(target.getNumVertices(), resultMap.size());

    // Add edges between the vertices in the graph
    for (V vertex : target.getVertices()) {
        for (E edge : target.getEdges(vertex)) {
            V neighbor = edge.getNeighbor(vertex);
            if (resultMap.containsKey(neighbor.getId())) {
                graph.addEdge(vertex, resultMap.get(neighbor.getId()));
            }
        }
    }

    // Add the vertices to the graph
    for (V vertex : target.getVertices()) {
        graph.addVertex(vertex);
    }

    // Add the edges to the graph
    for (E edge : target.getEdges()) {
        graph.addEdge(edge);
    }

    // Return the generated graph
    return graph;
}

