public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double xCenter = box.getX() + box.getWidth() / 2;
    double yCenter = box.getY() + box.getHeight() / 2;
    double halfWidth = box.getWidth() / 2;
    double halfHeight = box.getHeight() / 2;
    Box2D box1 = new Box2D(xCenter - halfWidth, yCenter - halfHeight, halfWidth, halfHeight);
    Box2D box2 = new Box2D(xCenter + halfWidth, yCenter - halfHeight, halfWidth, halfHeight);
    return new Pair<Box2D, Box2D>(box1, box2);
}

