public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < str.length()) {
                c = str.charAt(i + 1);
                if (c == 'n') {
                    sb.append('\n');
                    i++;
                } else if (c == 'r') {
                    sb.append('\r');
                    i++;
                } else if (c == 't') {
                    sb.append('\t');
                    i++;
                } else if (c == 'b') {
                    sb.append('\b');
                    i++;
                } else if (c == 'f') {
                    sb.append('\f');
                    i++;
                } else if (c == '\\') {
                    sb.append('\\');
                    i++;
                } else if (c == '\'') {
                    sb.append('\'');
                    i++;
                } else if (c == '\"') {
                    sb.append('\"');
                    i++;
                } else if (c == 'u') {
                    if (i + 5 < str.length()) {
                        String hex = str.substring(i + 2, i + 6);
                        sb.append((char) Integer.parseInt(hex, 16));
                        i += 5;
                    } else {
                        throw new Exception("Invalid unicode escape sequence");
                    }
                } else {
                    throw new Exception("Invalid escape sequence");
                }
            } else {
                throw new Exception("Invalid escape sequence");
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

